    "p": "B",
    "e": "Good idea. We should also bring a knife — we could cut rope, open coconuts, and build a shelter with it.",
    "v": "Ý hay. Mình cũng nên mang một con dao — có thể cắt dây, bổ dừa và dựng chỗ trú với nó."
